<?php
namespace Tests\Feature;
use App\Models\ShopUser;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Support\Facades\{DB,Mail};
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Str;
use Tests\TestCase;
class RetailWorkflowTest extends TestCase {
 use DatabaseTransactions;
 protected function setUp():void {parent::setUp();
  // Existing development orders are outside this test's mail batch; transaction rollback restores them.
  DB::table('order_email_outbox')->whereNull('sent_at')->update(['available_at'=>now()->addDay()]);
 }
 private function staff($role='super_admin'){ $id=DB::table('users')->insertGetId(['name'=>'QA Retail Staff','email'=>Str::uuid().'@example.test','password_hash'=>bcrypt('Strong test password!'),'role'=>$role]);$u=ShopUser::find($id);$this->withSession(['auth_version'=>$u->auth_version]);$this->actingAs($u);return $u;}
 private function publish($extra=[]){return ['name'=>'QA Retail Saree','description'=>'QA real workflow description','brand'=>DB::table('brands')->value('name'),'category'=>DB::table('categories')->value('name'),'image'=>'/images/gold.jpg','images'=>['/images/gold.jpg'],'price'=>1200,'stock'=>8,'publication_status'=>'published','size_options'=>['XS','S','M','L','XL'],'variants'=>[['type'=>'Unstitched','regular_price'=>1200,'sale_enabled'=>false,'sale_price'=>null,'stock'=>8,'enabled'=>true],['type'=>'Stitched','regular_price'=>1,'sale_enabled'=>false,'sale_price'=>null,'stock'=>0,'enabled'=>false]],...$extra];}
 private function checkout($p,$a){return ['name'=>'QA Retail Buyer','email'=>'qa-retail@example.test','phone'=>'03001234567','address'=>'QA shipping address','city'=>'Lahore','country'=>'Pakistan','postal_code'=>'54000','payment_method'=>'cod','checkout_token'=>(string)Str::uuid(),'items'=>[['id'=>$p,'variant_id'=>$a,'quantity'=>1]]];}
 public function test_draft_review_publish_and_permission_boundaries():void {
  $this->staff();$draft=$this->postJson('/api/admin/products',['name'=>'QA Incomplete Draft','publication_status'=>'draft'])->assertOk();$id=$draft->json('id');$this->assertDatabaseHas('products',['id'=>$id,'active'=>0,'publication_status'=>'draft']);$this->assertFalse(collect($this->getJson('/api/catalog')->json('products'))->contains('id',$id));$this->postJson('/api/admin/products',['name'=>'QA Incomplete Publish','publication_status'=>'published'])->assertUnprocessable();$this->deleteJson('/api/admin/products',['id'=>$id])->assertUnprocessable();
  $this->putJson('/api/admin/products',['id'=>$id,...$this->publish()])->assertOk();$p=collect($this->getJson('/api/catalog')->json('products'))->firstWhere('id',$id);$this->assertEquals('published',$p['publication_status']);$this->assertEquals(6200,$p['variants'][1]['price']);$this->assertArrayNotHasKey('cost_price',$p);$this->assertEquals(5,count($p['size_options']));
  $this->staff('staff');$this->putJson('/api/admin/products',['id'=>$id,...$this->publish()])->assertForbidden();$this->getJson('/api/admin/media')->assertOk();
 }
 public function test_five_original_dimension_images_order_and_asset_metadata():void {
  $this->staff('product_manager');$files=array_map(fn($i)=>UploadedFile::fake()->image('retail-'.$i.'.png',200,350),range(1,5));$r=$this->post('/api/admin/media',['images'=>$files],['Accept'=>'application/json'])->assertCreated()->assertJsonCount(5,'images');$paths=$r->json('images');
  try{foreach($paths as $path){$this->assertDatabaseHas('media_assets',['path'=>$path,'width'=>200,'height'=>350,'kind'=>'image']);$info=getimagesize(storage_path('app/public/products/'.basename($path)));$this->assertEquals([200,350],[$info[0],$info[1]]);}$ordered=array_reverse($paths);$result=$this->postJson('/api/admin/products',$this->publish(['images'=>$ordered,'image'=>$ordered[0]]))->assertOk();$id=$result->json('id');$this->assertEquals($ordered[0],DB::table('products')->find($id)->image);$this->assertCount(5,DB::table('product_media')->where('product_id',$id)->get());$this->assertEquals($ordered[0],DB::table('product_media as pm')->join('media_assets as a','a.id','=','pm.asset_id')->where('pm.product_id',$id)->where('pm.is_primary',true)->value('a.path'));$this->getJson('/api/admin/media')->assertOk();$this->postJson('/api/admin/products',$this->publish(['images'=>[...$paths,$paths[0]]]))->assertUnprocessable();}
  finally{foreach($paths as $path)@unlink(storage_path('app/public/products/'.basename($path)));}
 }
 public function test_video_validation_taxonomy_duplicates_and_category_image():void {
  $this->staff('product_manager');$this->post('/api/admin/media',['video'=>UploadedFile::fake()->create('evil.php',10,'application/x-php')],['Accept'=>'application/json'])->assertUnprocessable();$this->postJson('/api/admin/products',$this->publish(['video_url'=>'javascript:alert(1)']))->assertUnprocessable();$this->postJson('/api/admin/products',$this->publish(['video_url'=>'https://example.test/clip.mp4']))->assertOk();
  $name='QA Category '.Str::uuid();$this->postJson('/api/admin/categories',['name'=>$name,'image'=>'/images/gold.jpg'])->assertOk();$this->postJson('/api/admin/categories',['name'=>'  '.$name.'  '])->assertUnprocessable();$this->assertDatabaseHas('categories',['name'=>$name,'image'=>'/images/gold.jpg']);$this->postJson('/api/admin/brands',['name'=>'QA Brand '.Str::uuid(),'image'=>'/images/gold.jpg'])->assertUnprocessable();
 }
 public function test_actual_video_upload_and_range_playback():void {
  $this->staff('product_manager');$copy=tempnam(sys_get_temp_dir(),'retail-video');copy(base_path('tests/fixtures/flower.mp4'),$copy);$file=new UploadedFile($copy,'flower.mp4','video/mp4',null,true);
  $r=$this->post('/api/admin/media',['video'=>$file],['Accept'=>'application/json'])->assertCreated();$path=$r->json('video');
  try{$this->assertDatabaseHas('media_assets',['path'=>$path,'mime'=>'video/mp4','kind'=>'video']);$this->get($path)->assertOk()->assertHeader('Content-Type','video/mp4');$this->get($path,['Range'=>'bytes=0-99'])->assertStatus(206)->assertHeader('Content-Length','100');$this->postJson('/api/admin/products',$this->publish(['video_url'=>$path]))->assertOk();}
  finally{@unlink(storage_path('app/public/videos/'.basename($path)));@unlink($copy);}
 }
 public function test_media_cleanup_is_dry_by_default_and_preserves_referenced_files():void {
  DB::table('media_assets')->update(['created_at'=>now()]);$name=bin2hex(random_bytes(16)).'.webp';$path='/media/products/'.$name;$file=storage_path('app/public/products/'.$name);$trash=storage_path('app/private/media-trash/'.date('Y-m-d').'/'.$name);file_put_contents($file,'QA disposable cleanup fixture');$id=DB::table('media_assets')->insertGetId(['path'=>$path,'kind'=>'image','mime'=>'image/webp','bytes'=>filesize($file),'created_at'=>now()->subDays(10)]);
  try{$this->artisan('media:prune')->assertSuccessful();$this->assertFileExists($file);$this->assertNull(DB::table('media_assets')->find($id)->trashed_at);$category=DB::table('categories')->value('id');DB::table('categories')->where('id',$category)->update(['image'=>$path]);$this->artisan('media:prune',['--execute'=>true])->assertSuccessful();$this->assertFileExists($file);DB::table('categories')->where('id',$category)->update(['image'=>null]);$this->artisan('media:prune',['--execute'=>true])->assertSuccessful();$this->assertFileDoesNotExist($file);$this->assertFileExists($trash);$this->assertNotNull(DB::table('media_assets')->find($id)->trashed_at);}
  finally{@unlink($file);@unlink($trash);}
 }
 public function test_untracked_inventory_is_available_without_fabricated_stock_or_restock():void {
  $this->staff();$r=$this->postJson('/api/admin/products',$this->publish(['inventory_tracking'=>false]))->assertOk();$id=$r->json('id');$a=DB::table('product_variants')->where('product_id',$id)->where('type','Unstitched')->value('id');$catalog=collect($this->getJson('/api/catalog')->json('products'))->firstWhere('id',$id);$this->assertNull($catalog['stock']);$this->assertTrue($catalog['variants'][0]['available']);$order=$this->postJson('/api/orders',$this->checkout($id,$a))->assertCreated();$o=DB::table('orders')->where('reference',$order->json('reference'))->first();$this->assertDatabaseHas('order_items',['order_id'=>$o->id,'stock_reserved'=>0]);$this->assertEquals(8,DB::table('product_variants')->find($a)->stock);$this->putJson('/api/admin/orders',['id'=>$o->id,'status'=>'Cancelled'])->assertOk();$this->assertEquals(8,DB::table('product_variants')->find($a)->stock);
 }
 public function test_realistic_dispatch_validation_and_notification_attempt_history():void {
  Mail::fake();config(['mail.default'=>'smtp']);$this->staff();$r=$this->postJson('/api/admin/products',$this->publish())->assertOk();$id=$r->json('id');$a=DB::table('product_variants')->where('product_id',$id)->where('type','Unstitched')->value('id');$order=$this->postJson('/api/orders',$this->checkout($id,$a))->assertCreated();$o=DB::table('orders')->where('reference',$order->json('reference'))->first();
  foreach(['Confirmed','Processing','Packed'] as $status)$this->putJson('/api/admin/orders',['id'=>$o->id,'status'=>$status])->assertOk();$this->putJson('/api/admin/orders',['id'=>$o->id,'status'=>'Shipped'])->assertUnprocessable();$this->assertDatabaseHas('orders',['id'=>$o->id,'status'=>'Packed']);$this->putJson('/api/admin/orders',['id'=>$o->id,'status'=>'Shipped','delivery_method'=>'direct','dispatched_at'=>now()->addDay()->toIso8601String()])->assertUnprocessable();$this->putJson('/api/admin/orders',['id'=>$o->id,'status'=>'Shipped','delivery_method'=>'direct','courier_name'=>'Unused carrier'])->assertOk()->assertJsonPath('order.courier_name',null);$this->assertNotNull(DB::table('orders')->find($o->id)->dispatched_at);$repeat=$this->putJson('/api/admin/orders',['id'=>$o->id,'status'=>'Shipped','delivery_method'=>'direct'])->assertOk();$this->assertArrayNotHasKey('checkout_token',$repeat->json('order'));$this->assertArrayNotHasKey('request_hash',$repeat->json('order'));$this->assertEquals(5,DB::table('order_email_outbox')->where('order_id',$o->id)->count());$this->assertEquals(5,\App\Support\OrderEmails::deliver());$this->getJson('/api/admin/order-notifications?id='.$o->id)->assertOk()->assertJsonCount(5,'notifications')->assertJsonPath('notifications.0.outcomes.0.outcome','accepted');Mail::assertSent(\App\Mail\OrderUpdate::class,function($mail){return $mail->details['order']['status']==='Shipped'&&str_contains($mail->render(),'QA shipping address');});$this->staff('product_manager');$this->getJson('/api/admin/order-notifications?id='.$o->id)->assertForbidden();
 }
}
